variables.vent_eff:
{% if vent < 0 %}-999 {% else %}
  {% set r = rafales if rafales > vent else vent %}
  {% set p = S.vent_rafales_part %}
  {{ [((vent * (1 - p) + r * p) - S.vent_socle), 0]
     | max | round(1) }}
{% endif %}

variables.effet_vent:
{% set v = vent_eff | float(-999) %} {% if v < 0 %}0 {% else %}
  {% set c = S.vent_chaud if socle > S.vent_bascule
             else S.vent_frais %}
  {% if t_ext > S.vent_tiede %}
    {% set hr = hr_ext if hr_ext > -900 else 50 %}
    {% set fh = [[((hr - S.vent_hr_sec)
                 / (S.vent_hr_moite - S.vent_hr_sec)),
                 0] | max, 1] | min %}
    {% set cf = S.vent_fournaise_sec * (1 - fh)
              + S.vent_fournaise_c * fh %}
    {% set ft = [((t_ext - S.vent_tiede)
                / (S.vent_fournaise - S.vent_tiede)), 1] | min %}
    {% set c = c * (1 - ft) + cf * ft %}
  {% endif %}
  {{ [[(c * v), S.vent_plancher] | max,
      S.vent_fournaise_max] | min | round(1) }}
{% endif %}

variables.effet_soleil:
{% if elevation > S.elev_seuil and solaire > S.soleil_seuil %}
  {% set fa = sin(elevation * pi / 180)
              if S.soleil_angle == 'sinus' else 1 %}
  {{ [((solaire / S.soleil_div) * fa) | round(1),
      S.soleil_max] | min }}
{% else %}0{% endif %}

variables.effet_pluie:
{% if S.pluie_effet == 0 or pluie_taux < S.pluie_notable %}0 {% else %}
  {% set f = [(pluie_taux / S.pluie_effet_taux), 1] | min %}
  {% set v = [(vent_eff | float(0)), 0] | max %}
  {% set fw = 1 + ([v, 30] | min) / 60 %}
  {{ (S.pluie_effet * f * fw) | round(1) }}
{% endif %}

variables.effet_nuit:
{% set n = state_attr(E.meteo, 'cloud_coverage') %} {% if S.nuit_claire == 0 or elevation > -3 or n is none %}0 {% elif (n | float(100)) >= S.nuit_nuages %}0 {% else %}
  {{ (S.nuit_claire
      * (1 - (n | float(100)) / S.nuit_nuages)) | round(1) }}
{% endif %}

