variables.phrase_ressenti:
{% set e = (ressenti - t_ext) | round(1) %} {% set e_fr = (e | abs) | string | replace('.', ',') %} {% if t_ext < -900 %}{{ '' }} {% elif base == 'thermometre' %}
  {# ⚠ ON LE DIT. Sans capteur d'humidex, ce chiffre n'est que le
     thermomètre corrigé du vent et du soleil : un jour lourd, il
     sous-estime largement. Le taire, c'est afficher 27 °C un jour
     où l'on en ressent 37. #}
  humidex indisponible — l’humidité n’est pas comptée
{% elif e | abs < 0.6 %}
  le ressenti colle au thermomètre
{% elif e > 0 %}
  {{ e_fr }} °C de plus qu’au thermomètre —
  {% if (effet_vent | float(0)) > 0.3 %}
    {# La journée où le vent ne soulage plus. Elle mérite d'être
       nommée : c'est exactement celle où l'on croit qu'il aide. #}
    même le vent réchauffe, il n’apporte plus rien
  {% elif (effet_soleil | float(0)) >= 1.5 %}
    le soleil y est pour
    {{ effet_soleil | string | replace('.', ',') }} °C
  {% else %}c’est l’humidité qui pèse{% endif %}
{% else %}
  {# On nomme le terme qui pèse le plus lourd, pas le vent par
     défaut : un soir d'averse, « le vent en emporte 0,4 °C » sous
     un écart de 2 °C ne collait à rien de ce qu'on voyait. #}
  {% set ev = (effet_vent | float(0)) | abs %}
  {% set ep = (effet_pluie | float(0)) | abs %}
  {% set en = (effet_nuit | float(0)) | abs %}
  {{ e_fr }} °C de moins qu’au thermomètre —
  {% if ep >= ev and ep > 0.4 %}
    l’averse en emporte {{ ep | string | replace('.', ',') }} °C
  {% elif en > ev and en > 0.4 %}
    le ciel dégagé en emporte
    {{ en | string | replace('.', ',') }} °C
  {% else %}
    le vent en emporte {{ ev | string | replace('.', ',') }} °C
  {% endif %}
{% endif %}

attributes.vent_t:
{% set prec = this.attributes.get('vent_t', {})
              if this is defined and this.attributes is defined else {} %}
{% set h0 = prec.get('h', []) if prec is mapping else [] %} {% set h0 = h0 if (h0 is iterable and h0 is not string) else [] %} {% set ts = now().timestamp() | round(0) %} {% set vieux = h0 | rejectattr('t', 'lt', ts - S.vent_fenetre_s)
                  | list %}

{% set ref = (vieux | sort(attribute='t') | first).v | float(-999)
             if vieux | count > 0 else -999 %}
{% set d = (vent - ref) | round(1)
           if (vent > -900 and ref > -900) else -999 %}
{% set f = (((ts - (vieux | map(attribute='t') | min)) / 60)
            | round(0)) if vieux | count > 0 else 0 %}
{% set d = d if f >= S.vent_min_fenetre else -999 %}
{% set s = '' if d < -900
           else ('hausse' if d >= S.vent_seuil
                 else ('baisse' if d <= (0 - S.vent_seuil)
                       else 'stable')) %}
{% if s == 'hausse' %}{% set tx = 'le vent se lève' %} {% elif s == 'baisse' %}{% set tx = 'le vent faiblit' %} {% elif s == 'stable' %}{% set tx = 'vent régulier' %} {% else %}{% set tx = '' %}{% endif %}
{% set dern = (vieux | map(attribute='t') | max)
              if vieux | count > 0 else 0 %}
{% set neuf = (vieux + [{'t': ts, 'v': vent}])
              if (vent > -900 and (ts - dern) >= S.vent_pas_s)
              else vieux %}

{{ {'h': neuf, 'd': d, 'f': f, 's': s, 'tx': tx} }}

attributes.baro:
{% set prec = this.attributes.get('baro', {})
              if this is defined and this.attributes is defined else {} %}
{% set h0 = prec.get('h', []) if prec is mapping else [] %} {% set h0 = h0 if (h0 is iterable and h0 is not string) else [] %} {% set ts = now().timestamp() | round(0) %} {% set vieux = h0 | rejectattr('t', 'lt', ts - S.baro_fenetre_s)
                  | list %}

{# ── L'écart avec le plus ancien point encore dans la fenêtre ── #} {% set ref = (vieux | sort(attribute='t') | first).p | float(-999)
             if vieux | count > 0 else -999 %}
{% set d = (pression - ref) | round(1)
           if (pression > 0 and ref > 0) else -999 %}

{# ⚠ Sur quelle durée porte réellement l'écart. Au démarrage la
   fenêtre est vide : le premier écart portera sur neuf minutes
   et ne vaudra pas grand-chose. La carte l'affiche (« sur
   12 min ») plutôt que de laisser croire à une tendance sur 3 h.
   Un chiffre approché posé sans son domaine de validité se paie
   en confiance sur tous les autres. #}
{% set f = (((ts - (vieux | map(attribute='t') | min)) / 60)
            | round(0)) if vieux | count > 0 else 0 %}

{# ⚠ Une fenêtre trop courte n'a pas de tendance, elle a du bruit.
   On repasse alors `d` à −999 : la carte affiche « tendance en
   cours de mesure » au lieu d'un écart de 0,2 hPa présenté comme
   les vrais. #}
{% set d = d if f >= S.baro_min_fenetre else -999 %}
{% set s = '' if d < -900
           else ('hausse' if d >= S.baro_leger
                 else ('baisse' if d <= (0 - S.baro_leger)
                       else 'stable')) %}

{# Le baromètre ne PRÉDIT pas la pluie, il annonce un changement
   de régime. La phrase reste donc prudente : c'est ce que les
   marins en tirent, pas plus.
   ⚠ SEIZE CARACTÈRES MAXIMUM — c'est le libellé d'une tuile qui
     partage la largeur de la carte avec deux autres. « en
     baisse, le temps se gâte » sortait tronqué. #}
{% set a = d | abs %} {% if d < -900 %}{% set tx = '' %} {% elif a < S.baro_leger %}{% set tx = 'temps installé' %} {% elif s == 'baisse' %}
  {% set tx = 'chute rapide' if a >= S.baro_fort
              else ('le temps se gâte' if a >= S.baro_net
                    else 'légère baisse') %}
{% else %}
  {% set tx = 'ça se dégage' if a >= S.baro_fort
              else ('amélioration' if a >= S.baro_net
                    else 'légère hausse') %}
{% endif %}
{# ── On n'ajoute un point que si le dernier a plus de 9 minutes.
   Le minuteur passe toutes les 5 minutes et chaque capteur météo
   qui bouge déclenche en plus : sans ce pas, la liste enflerait
   à plusieurs centaines de points par jour, tous réécrits dans
   la base à chaque calcul. #}
{% set dern = (vieux | map(attribute='t') | max)
              if vieux | count > 0 else 0 %}
{% set neuf = (vieux + [{'t': ts, 'p': pression}])
              if (pression > 0 and (ts - dern) >= S.baro_pas_s)
              else vieux %}

{{ {'h': neuf, 'd': d, 'f': f, 's': s, 'tx': tx} }}
